import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();

        int substituidos = 0;
        int consertados = 0;

        for (int i = 0; i < n; i++) {
            int x = sc.nextInt();

            if (x < 50) {
                substituidos++;
            } else if (x < 85) {
                consertados++;
            }
        }

        System.out.println(substituidos + " " + consertados);

        sc.close();
    }
}
